export default function install(app) {
  const control=document.createElement("calcite-action");
  control.setAttribute("icon","legend");control.setAttribute("text","Capacity map legend");control.setAttribute("title","Capacity map legend");control.setAttribute("scale","m");control.className="esri-widget";
  const panel=document.createElement("div");panel.className="esri-widget";Object.assign(panel.style,{display:"none",width:"280px",padding:"14px",boxSizing:"border-box",background:"var(--calcite-color-foreground-1,#fff)",boxShadow:"0 1px 4px rgba(0,0,0,.3)",maxHeight:"min(520px,70vh)",overflow:"auto"});
  const head=document.createElement("div");Object.assign(head.style,{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:"10px"});const title=document.createElement("strong");title.textContent="NIE capacity symbols";const close=document.createElement("calcite-action");close.setAttribute("icon","x");close.setAttribute("text","Close legend");close.setAttribute("scale","s");head.append(title,close);panel.append(head);
  const pin=(label,fillA,fillB=fillA)=>`<svg width="30" height="38" viewBox="0 0 30 38" aria-hidden="true"><defs><clipPath id="pin-${label}-${fillA.replace('#','')}"><path d="M15 37 C13 31 3 23 3 14 A12 12 0 0 1 27 14 C27 23 17 31 15 37Z"/></clipPath></defs><path d="M15 37 C13 31 3 23 3 14 A12 12 0 0 1 27 14 C27 23 17 31 15 37Z" fill="${fillA}" stroke="white" stroke-width="1.5"/><rect x="15" y="0" width="15" height="38" fill="${fillB}" clip-path="url(#pin-${label}-${fillA.replace('#','')})"/><path d="M15 37 C13 31 3 23 3 14 A12 12 0 0 1 27 14 C27 23 17 31 15 37Z" fill="none" stroke="white" stroke-width="1.5"/><text x="15" y="18" text-anchor="middle" font-family="Arial" font-size="9" font-weight="700" fill="white">${label}</text></svg>`;
  const section=heading=>{const h=document.createElement("div");h.textContent=heading;Object.assign(h.style,{fontWeight:"600",fontSize:"0.85rem",margin:"12px 0 6px"});panel.append(h)};
  const row=(symbol,label)=>{const el=document.createElement("div");Object.assign(el.style,{display:"grid",gridTemplateColumns:"38px 1fr",alignItems:"center",gap:"8px",minHeight:"34px",fontSize:"0.85rem"});const mark=document.createElement("span");mark.innerHTML=symbol;const text=document.createElement("span");text.textContent=label;el.append(mark,text);panel.append(el)};
  section("Substation symbols");row(pin("P","#2e8540"),"P — Primary substation");row(pin("PP","#2e8540","#f5a623"),"PP — Dual-primary or paired site; halves show each primary status");row(pin("BP","#386cb0"),"BP — Bulk supply point");
  section("Capacity status");const swatch=color=>`<span style="display:inline-block;width:22px;height:22px;border-radius:2px;background:${color};border:1px solid rgba(0,0,0,.18)"></span>`;row(swatch("#2e8540"),"Green — capacity available");row(swatch("#f5a623"),"Amber — limited capacity");row(swatch("#d64545"),"Red — constrained or no capacity");row(swatch("#386cb0"),"Blue — information / bulk status");row(swatch("#707070"),"Grey — no status available");
  const note=document.createElement("p");note.textContent="Colours reflect the active Demand, Generation or Fault-level mode. Split pins show the status of each component.";Object.assign(note.style,{margin:"10px 0 0",fontSize:"0.78rem",lineHeight:"1.35",color:"var(--calcite-color-text-2)"});panel.append(note);
  const toggle=()=>{const opening=panel.style.display==="none";panel.style.display=opening?"block":"none";control.toggleAttribute("active",opening)};const closePanel=()=>{panel.style.display="none";control.removeAttribute("active")};control.addEventListener("click",toggle);close.addEventListener("click",closePanel);app.view.ui.add(control,"bottom-left");app.view.ui.add(panel,"bottom-left");
  app.onCleanup(()=>{control.removeEventListener("click",toggle);close.removeEventListener("click",closePanel);app.view.ui.remove(control);app.view.ui.remove(panel);control.remove();panel.remove()});return {legend:true,symbolTypes:3,statusColours:5};
}